'use strict';

// MODULES //

var addon = require( '@stdlib/stats/base/dists/log-logistic/entropy/src/addon.node' );


// MAIN //

/**
* Returns the differential entropy of a log-logistic distribution with scale parameter `alpha` and shape parameter `beta`.
*
* @private
* @param {PositiveNumber} alpha - scale parameter
* @param {PositiveNumber} beta - shape parameter
* @returns {number} entropy
*
* @example
* var y = entropy( 1.0, 3.0 );
* // returns ~0.901
*
* @example
* var y = entropy( 4.0, 3.0 );
* // returns ~2.288
*
* @example
* var y = entropy( NaN, 3.0 );
* // returns NaN
*
* @example
* var y = entropy( 2.0, NaN );
* // returns NaN
*
* @example
* var y = entropy( -1.0, 3.0 );
* // returns NaN
*
* @example
* var y = entropy( 2.0, -1.0 );
* // returns NaN
*/
function entropy( alpha, beta ) {
	return addon( alpha, beta );
}


// EXPORTS //

module.exports = entropy;
